def compute(vars):
    regional_government_exposure = vars["v1"]
    sovereign_government_exposure = vars["v2"]
    total_exposure = regional_government_exposure + sovereign_government_exposure

    return {
        "value": total_exposure,
        "trace": {
            "regional_government_exposure": regional_government_exposure,
            "sovereign_government_exposure": sovereign_government_exposure,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
